From 6df97d459c1aa1f5a7e9c7c287c30d701dab7c47 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 08:11:09 +0100
Subject: [PATCH] xdgshellwindow: re-place applet popups after an interactive
 resize

Position requests from applet popups are ignored while they're being
moved or resized, so a Meta+right-drag from the anchored edge left the
popup detached from its applet; apply the last requested position again.

BUG: 520409
---
 src/xdgshellwindow.cpp | 5 +++++
 1 file changed, 5 insertions(+)

diff --git a/src/xdgshellwindow.cpp b/src/xdgshellwindow.cpp
index 6f3b1b8d0e..006195385f 100644
--- a/src/xdgshellwindow.cpp
+++ b/src/xdgshellwindow.cpp
@@ -1672,6 +1672,11 @@ void XdgToplevelWindow::installPlasmaShellSurface(PlasmaShellSurfaceInterface *s
         }
     };
     connect(shellSurface, &PlasmaShellSurfaceInterface::positionChanged, this, updatePosition);
+    connect(this, &Window::interactiveMoveResizeFinished, this, [this, shellSurface, updatePosition] {
+        if (isAppletPopup() && shellSurface->isPositionSet()) {
+            updatePosition();
+        }
+    });
     connect(shellSurface, &PlasmaShellSurfaceInterface::openUnderCursorRequested, this, showUnderCursor);
     connect(shellSurface, &PlasmaShellSurfaceInterface::roleChanged, this, updateRole);
     connect(shellSurface, &PlasmaShellSurfaceInterface::panelTakesFocusChanged, this, [this] {
-- 
